// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz: amount to send and whether to use attacker or plain EOA
    function testFuzz_property(uint128 amount, bool useAttacker) public {
        // keep amount reasonable and non-zero so Put has effect and meets MinSum check possibility
        uint256 amt = bound(uint256(amount), 1 wei, 10 ether);

        // deploy attacker helper if requested
        Attacker attacker = new Attacker(c);

        address caller = useAttacker ? address(attacker) : address(0xBEEF);

        // fund the caller so they can send
        vm.deal(caller, amt);

        // record previous balance in mapping for caller
        uint256 before = c.Acc(caller).balance();

        // If using attacker, instruct it to reenter during its receive; otherwise behave as EOA
        if (useAttacker) {
            attacker.setReenter(true);
            vm.prank(caller);
            // call Put on behalf of attacker which will trigger its receive and attempt reentrancy
            (bool ok, ) = address(c).call{value: amt}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
            // we ignore ok here; the property is about final stored balance when Put returns normally
        } else {
            vm.prank(caller);
            c.Put{value: amt}(0);
        }

        // single assertion: after the external Put(...) call completes, the stored balance equals previous + msg.value
        // This is the universal rule the reference satisfies; the mutant allowing reentrancy can violate it for some inputs
        uint256 after = c.Acc(caller).balance();
        assertTrue(after == before + amt);
    }
}

// Minimal attacker that on receive will try to reenter Put once
contract Attacker {
    C public target;
    bool public reenter;
    bool entered;

    constructor(C _t) {
        target = _t;
        reenter = false;
        entered = false;
    }

    function setReenter(bool r) external {
        reenter = r;
    }

    // receive triggers a reentrant call to Put
    receive() external payable {
        // only attempt one reentrant call to avoid infinite recursion
        if (reenter && !entered) {
            entered = true;
            // call Put again with 0 to attempt to reenter and manipulate stored balance
            // forward a small amount (0) to focus on reentrancy sequence; target will still see msg.value 0
            // this is enough to trigger differing behavior when guard is broken
            target.Put{value: 0}(0);
        }
    }
}

