    C c;
    function setUp() public { c = new C(address(this)); }

    // We fuzz the depositor address and the deposit amount.
    // General rule: after Put(amount) completes, the holder's stored balance must reflect the deposit
    // (i.e. be >= amount if starting from zero) AND the most recent Log History entry corresponds to that Put call
    // observing the deposit (we enforce by checking that History's last entry Val equals the sent value).
    // The mutant that logs before updating acc.balance can produce histories inconsistent with stored state/timing.
    function testFuzz_property(address depositor, uint256 amount) public {
