        vm.prank(depositor);
        c.Put{value: amount}(0);

        // Read holder state and last log entry via public getters
        (uint unlockTime, uint balance) = c.Acc(depositor);
        // History is public in Log; access last entry via History(uint)
        // We access index 0 because for this test we start from fresh Log (setUp passed address(this) but Log was constructed empty)
        // However History is a public array on Log; C.LogFile is public in C so we can call LogFile().History(i)
        // The autogenerated getter for Message[] History returns (address,string,uint,uint) so we can read index 0
