        // The invariant we assert: the last log entry records the deposit value we just sent, and the holder balance reflects the deposit
        // This is a single assertTrue reading c's public surface (balance via Acc getter, and History via LogFile().History)
        assertTrue(sender0 == depositor && val0 == amount && balance >= amount);
    }
}

