contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: deposit some value, then attempt a Collect and observe whether it succeeded.
    // Parameters:
    // depositor: the account that will be used as msg.sender for Put and Collect (must be this contract)
    // depositAmount: amount to send to Put
    // unlockTime: unlock time passed to Put
    // withdrawAmount: amount to request in Collect
    function check(uint depositAmount, uint unlockTime, uint withdrawAmount) public {
        // Precondition: this contract must hold enough ETH to fund the deposit
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Make the deposit (calls Put) — this is a state-changing call and must be top-level
        c.Put{value: depositAmount}(unlockTime);

        // Attempt withdrawal via Collect; capture whether call reverted by using low-level call on c
        // Since Collect is nonReentrant_ and public, we call it via address(c).call to capture success boolean
        (bool ok, bytes memory) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        // If the withdrawal call succeeded, then on the original contract P it must have been that
        // the stored balance before withdrawal was at least MinSum. We can observe the post-call balance
        // via the public mapping getter Acc(address).balance; however the getter returns the Holder struct's first field unlockTime
        // and second field balance is accessible as Acc(address).balance (auto-generated). So read it now.
        uint afterBalance = c.Acc(address(this)).balance;
        uint minSum = c.MinSum();

        // If the Collect call succeeded, then the pre-withdrawal balance was afterBalance + withdrawAmount.
        // Enforce the rule: if ok==true then (afterBalance + withdrawAmount) >= minSum
        assert(!ok || (afterBalance + withdrawAmount) >= minSum);
    }

    // Allow the contract to receive ETH for funding deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: caller will attempt to withdraw 'am' wei
    function run(uint am) public payable {
        require(address(this).balance >= am, "need funds to attempt withdrawal");
        bool reverted;
        try c.Collect{value: 0}(am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // If the call did not revert, then either it was reverted=false and the precondition
        // from the original contract requires that before withdrawal the caller's balance >= MinSum
        // We cannot read the internal balance, but we can read c.MinSum() public getter.
        // Thus assert: if call succeeded then am > 0 implies MinSum <= address(c).balance + 0 OR am == 0
        // More precisely: original allowed withdrawal only when caller balance >= MinSum and >= am and unlock passed.
        // We express a rule relating success to am: if succeeded then am <= address(c).balance (the contract's balance)
        // and am >= 0 trivially. To capture MinSum requirement we assert that if not reverted then c.MinSum() <= address(c).balance || am == 0;
        // This uses observable address(c).balance as an upper bound proxy: if the contract holds less than MinSum in total, no one could have withdrawn requiring >= MinSum.
        uint minSum = c.MinSum();
        // General rule: if Collect did not revert, then the contract's total balance before call was at least minSum.
        // Since we cannot read pre-call balance, we use current address(c).balance plus am as a lower bound for pre-call balance when call succeeded (because success would have transferred am out).
        // If call succeeded, pre-call balance = address(c).balance + am. So require that equals >= minSum.
        assert(reverted || (address(c).balance + am >= minSum));
    }
    receive() external payable { }
}

